import{_ as e,W as i,X as l,a2 as a}from"./framework-6a3aa88c.js";const r={},t=a('<h1 id="学习约定-快速吸收模式" tabindex="-1"><a class="header-anchor" href="#学习约定-快速吸收模式" aria-hidden="true">#</a> 学习约定：快速吸收模式</h1><h2 id="_1-课堂节奏" tabindex="-1"><a class="header-anchor" href="#_1-课堂节奏" aria-hidden="true">#</a> 1. 课堂节奏</h2><p>每个知识单元只引入一个核心概念，并按下面顺序讲解：</p><ol><li><strong>白话引入</strong>：它解决什么具体问题？</li><li><strong>动手看到结果</strong>：命令逐条执行，每一步解释输入和预期输出。</li><li><strong>解释原理</strong>：只解释刚才已经观察到的现象。</li><li><strong>常见问题</strong>：问题和答案直接给出。</li><li><strong>压缩记忆</strong>：最后只保留 3～5 个结论。</li></ol><p>默认不安排问答验收、考试、自评分或等待过关。快速吸收指减少低价值内容，不代表跳过基础、堆叠术语。</p><h2 id="_2-三本账" tabindex="-1"><a class="header-anchor" href="#_2-三本账" aria-hidden="true">#</a> 2. 三本账</h2><p>学习期间始终维护三类记录：</p><ul><li><strong>对象账</strong>：我创建了什么，它的 owner、selector、状态分别是什么？</li><li><strong>流量账</strong>：请求从哪里来，逐跳经过什么，在哪一跳失败？</li><li><strong>变更账</strong>：我改了什么，观察到什么，如何回退？</li></ul><p>需要留证时统一记到 <code>学习记录/</code>，不要只在终端滚屏里留下证据。</p><h2 id="_3-命令纪律" tabindex="-1"><a class="header-anchor" href="#_3-命令纪律" aria-hidden="true">#</a> 3. 命令纪律</h2><ul><li>每次先确认 context：<code>kubectl config current-context</code>。</li><li>所有课程资源进入独立 Namespace，避免误伤别的环境。</li><li>删除前先确认对象类型、名称和 Namespace。</li><li><code>apply</code> 后必须 <code>get/describe</code> 回读，不能把 “configured” 当作成功上线。</li><li>遇到故障先收集状态、Events、日志，再修改或重建。</li><li>不使用 <code>latest</code> 镜像标签作为正式实验版本。</li><li>清理命令单独列出，不与创建命令绑在一条长命令中。</li></ul><h2 id="_4-内容压缩原则" tabindex="-1"><a class="header-anchor" href="#_4-内容压缩原则" aria-hidden="true">#</a> 4. 内容压缩原则</h2><p>每一课优先保留：</p><ul><li>一句核心结论；</li><li>一张对象关系或请求链路图；</li><li>一个最小正确示例；</li><li>一个最常见故障；</li><li>一组“问题 + 直接回答”。</li></ul><p>低频字段和可随时查阅的参数不占课堂篇幅。需要时使用 <code>kubectl explain</code> 和官方文档查询。</p><h2 id="_5-我们如何配合" tabindex="-1"><a class="header-anchor" href="#_5-我们如何配合" aria-hidden="true">#</a> 5. 我们如何配合</h2><p>后续按概念依赖关系循序推进，并直接提供问题与答案。一个术语没有用白话解释和实际观察过，就不拿它解释下一个术语。你可以在下面三种情况打断我：</p><ol><li>某个概念没有听懂；</li><li>实际输出与课件不同；</li><li>希望对某个生产场景深入展开。</li></ol><p>否则课程直接向前推进，不安排等待回答的验收环节。</p>',19),o=[t];function n(c,d){return i(),l("div",null,o)}const h=e(r,[["render",n],["__file","01-学习约定.html.vue"]]);export{h as default};
